@import "./tokens.css";

*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  color-scheme: light;
  color: var(--color-gravy-text);
  background-color: var(--color-cream-counter);
}

html,
body {
  margin: 0;
  min-height: 100vh;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-body-size);
  font-weight: var(--text-body-weight);
  line-height: var(--text-body-line-height);
  color: var(--color-gravy-text);
  background-color: var(--color-cream-counter);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  min-height: 100vh;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  margin: 0;
  font-weight: normal;
}

p {
  margin: 0;
}

a {
  color: var(--color-ketchup-red);
}

button {
  font-family: inherit;
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
}

/* Focus ring per DESIGN.md: hard ink outline, never a soft glow */
:focus-visible {
  outline: 3px solid var(--color-gravy-ink);
  outline-offset: 2px;
}

